7	namespace Tsingtao.Supplier.WebApi.MiddleWare
8	{
9	    /// <summary>
10	    /// 
11	    /// </summary>
12	    public class UserAuthorizeMiddleWare : IMiddleware
13	    {
14	        private readonly IRightService _rightService;
15	
16	        /// <summary>
17	        /// 
18	        /// </summary>
19	        /// <param name="userService"></param>
20	        /// <param name="rightService"></param>
21	        public UserAuthorizeMiddleWare(IRightService rightService)
22	        {
23	            _rightService = rightService;
24	        }
25	
26	        /// <summary>
27	        /// 
28	        /// </summary>
29	        /// <param name="context"></param>
30	        /// <param name="next"></param>
31	        /// <returns></returns>
32	        public async Task InvokeAsync(HttpContext context, RequestDelegate next)
33	        {
34	            var endpoint = context.GetEndpoint();
35	
36	            if (endpoint == null)
37	            {
38	                await next(context);
39	                return;
40	            }
41	
42	            var userAuthAttr = endpoint.Metadata.GetMetadata<UserAuthorizeAttribute>();
43	
44	            if (userAuthAttr == null)
45	            {
46	                await next(context);
47	                return;
48	            }
49	
50	            var user = context.User;
51	            
52	            if (user.Identity == null || !user.Identity.IsAuthenticated)
53	            {
54	                context.Response.ContentType = ContentTypes.JSON;
55	                context.Response.StatusCode = StatusCodes.Status401Unauthorized;
56	                await context.Response.WriteAsync(BaseResult.Fail(ErrCodeEnum.NotLogin).ToJson());
57	                return;
58	            }
59	
60	            var userCid = user.GetUserCid();
61	
62	            if (string.IsNullOrWhiteSpace(userCid))
63	            {
64	                context.Response.ContentType = ContentTypes.JSON;
65	                context.Response.StatusCode = StatusCodes.Status401Unauthorized;
66	                await context.Response.WriteAsync(BaseResult.Fail(ErrCodeEnum.NotLogin).ToJson());
67	                return;
68	            }
69	
70	            var userInfo = user.GetFullUser(); // await _userService.GetUserInfoByCidFromCacheAsync(userCid);
71	
72	            if (userInfo == null)
73	            {
74	                context.Response.ContentType = ContentTypes.JSON;
75	                await context.Response.WriteAsync(BaseResult.Fail(ErrCodeEnum.NotLogin).ToJson());
76	                return;
77	            }
78	
79	            // 法人权限判定
80	            if (userAuthAttr.IsNeedLegalPerson && userInfo.IsLegal)
81	            {
82	                context.Response.ContentType = ContentTypes.JSON;
83	                await context.Response.WriteAsync(BaseResult.Fail(ErrCodeEnum.UnAuthorized).ToJson());
84	                return;
85	            }
86	
87	            // 管理员权限判定
88	            if (userAuthAttr.IsNeedManager && !(userInfo.IsLegal || userInfo.IsAdmin))
89	            {
90	                context.Response.ContentType = ContentTypes.JSON;
91	                await context.Response.WriteAsync(BaseResult.Fail(ErrCodeEnum.UnAuthorized).ToJson());
92	                return;
93	            }
94	
95	            if (!string.IsNullOrWhiteSpace(userAuthAttr.Roles) && !(userInfo.IsLegal || userInfo.IsAdmin) && !await _rightService.CheckUserRightsAsync(userCid, userAuthAttr.Roles.Split(',')))
96	            {
97	                context.Response.ContentType = ContentTypes.JSON;
98	                await context.Response.WriteAsync(BaseResult.Fail(ErrCodeEnum.UnAuthorized).ToJson());
99	                return;
100	            }
101	
102	            await next(context);
103	        }
104	    }
105	}

