33	            if (!TryRetrieveToken(context.Request, out string token))
34	            {
35	                // 检查是否有其他身份验证方式（如Cookie中的用户信息）
36	                if (!HasAlternativeAuthentication(context))
37	                {
38	                    await WriteUnauthorizedResponse(context, "接口无权访问！", 4000);
39	                    return;
40	                }
41	
42	                await _next(context);
43	                return;
44	            }
45	
46	            try
47	            {
48	                // 解密并验证Token
49	                if (!ValidateToken(token, out TokenInfo tokenInfo))
50	                {
51	                    await WriteUnauthorizedResponse(context, "Token无效！", 4000);
52	                    return;
53	                }
54	
55	                // 验证Token过期时间
56	                if (!TimeValidator(tokenInfo.Expires))
57	                {
58	                    await WriteUnauthorizedResponse(context, "Token超时！", 4000);
59	                    return;
60	                }
61	
62	                // Token验证通过，将用户信息存储到HttpContext
63	                if (tokenInfo != null)
64	                {
65	                    // 设置当前用户信息（根据你的UserInfo结构调整）
66	                    SetUserPrincipal(context, tokenInfo);
67	                }
68	
69	                await _next(context);
70	            }
71	            catch (Exception ex)
72	            {
73	                _logger.LogError(ex, "Token验证失败");
74	                await WriteUnauthorizedResponse(context, $"Token无效：{ex.Message}", 4000);
75	            }
76	        }
