78	        private bool ShouldSkipValidation(PathString path)
79	        {
80	            var pathString = path.Value?.ToLower() ?? "";
81	            _logger.LogInformation($"ShouldSkipValidation pathString{pathString}");
82	            return pathString.Contains("/auth/") ||
83	                   pathString.Contains("/cms/") ||
84	                   pathString.Contains("/contract/") ||
85	                   pathString.Contains("/portal/") ||
86	                   pathString.Contains("/esignredirect/") ||
87	                   pathString.Contains("/pub/") || // 添加其他无需验证的路径
88	                   pathString.Contains("/user/") ||
89	                   pathString.Contains("/wechatredirect");
90	        }
91	        private bool TryRetrieveToken(HttpRequest request, out string token)
92	        {
93	            token = null;
94	
95	            // 1. 尝试从Authorization头获取
96	            if (request.Headers.TryGetValue("Authorization", out StringValues authHeader))
97	            {
98	                var authValue = authHeader.ToString();
99	                if (!string.IsNullOrEmpty(authValue))
100	                {
101	                    token = authValue.StartsWith("Bearer ", StringComparison.OrdinalIgnoreCase)
102	                        ? authValue.Substring(7)
103	                        : authValue;
104	                    return true;
105	                }
106	            }
107	
108	            // 2. 尝试从Query String获取（可选）
109	            if (request.Query.TryGetValue("access_token", out StringValues queryToken))
110	            {
111	                token = queryToken.ToString();
112	                return true;
113	            }
114	
115	            return false;
116	        }
117	        private bool HasAlternativeAuthentication(HttpContext context)
118	        {
119	            // 这里实现你的其他认证方式检查
120	            // 例如检查Cookie中的用户信息
121	            // 假设UserInfo.Current是在其他地方设置的
122	
123	            // 注意：在.NET Core中，UserInfo.Current可能不再适用
124	            // 建议使用context.User.Identity或ClaimsPrincipal
125	
126	            // 示例：检查是否已经通过Cookie认证
127	            if (context.User?.Identity?.IsAuthenticated ?? false)
128	            {
129	                return true;
130	            }
131	
132	            // 或者检查特定的Cookie
133	            if (context.Request.Cookies.TryGetValue("UserAuth", out string userAuth))
134	            {
135	                // 验证Cookie内容
136	                return !string.IsNullOrEmpty(userAuth);
137	            }
138	
139	            return false;
140	        }
141	        private bool ValidateToken(string token, out TokenInfo tokenInfo)
142	        {
143	            tokenInfo = null;
144	
145	            try
146	            {
147	                string decryptedText = SecurityUtility.AESDecrypt(token);
148	                tokenInfo = JsonConvert.DeserializeObject<TokenInfo>(decryptedText);
149	
150	                return tokenInfo != null;
151	            }
152	            catch
153	            {
154	                return false;
155	            }
156	        }
157	        private bool TimeValidator(DateTime expires)
158	        {
159	            // 从配置获取Token过期时间扩展
160	            string tokenExExpiresValue = "30"; // 默认30分钟
161	                                               // 实际应该从配置读取，例如：
162	                                               // var configuration = context.RequestServices.GetService<IConfiguration>();
163	                                               // tokenExExpiresValue = configuration["Portal:TokenExExpires:value"] ?? "30";
164	
165	            if (int.TryParse(tokenExExpiresValue, out int extraMinutes))
166	            {
167	                return DateTime.Now < expires.AddMinutes(extraMinutes);
168	            }
169	
170	            return DateTime.Now < expires;
171	        }
172	
173	        private void SetUserPrincipal(HttpContext context, TokenInfo tokenInfo)
174	        {
175	            // 创建Claims
176	            List<Claim> claims = new(){
177	                new(ClaimTypes.NameIdentifier, tokenInfo.AppID),
178	                new(ClaimTypes.Name,tokenInfo.AppName),
179	                new("AppID", tokenInfo.AppID),
180	                new("AppName", tokenInfo.AppName)
181	            };
182	
183	            var identity = new ClaimsIdentity(claims, "CustomToken");
184	            context.User = new ClaimsPrincipal(identity);
185	        }
186	
