188	        private async Task WriteUnauthorizedResponse(HttpContext context, string errorMsg, int errorCode)
189	        {
190	            context.Response.StatusCode = StatusCodes.Status401Unauthorized;
191	            context.Response.ContentType = "application/json";
192	
193	            var result = new InterfaceAjaxResult
194	            {
195	                ErrorCode = errorCode,
196	                ErrorMsg = errorMsg
197	            };
198	
199	            var json = JsonConvert.SerializeObject(result);
200	            await context.Response.WriteAsync(json);
201	        }
202	    }
203	    public class InterfaceAjaxResult
204	    {
205	        public int ErrorCode { get; set; }
206	
207	        public string ErrorMsg { get; set; }
208	
209	        public object Data { get; set; }
210	
211	        public InterfaceAjaxResult()
212	        {
213	            ErrorCode = 0;
214	            ErrorMsg = "请求成功";
215	        }
216	    }
217	}

