39	        /// <inheritdoc/>
40	        public async Task<Tuple<ErrCodeEnum, string>> CreateCaptchaAsync(string phone)
41	        {
42	            var startTime = DateTime.Now.Date.ToLongUnixTimestamp();
43	            var endTime = DateTime.Now.AddDays(1).Date.ToLongUnixTimestamp();
44	            var captchaList = await _context.VerificationCodeList.CountAsync(q =>
45	                q.Target == phone && q.TargetType == CaptchaTarget.Phone &&
46	                q.SendTime > startTime &&
47	                q.SendTime < endTime);
48	
49	            if (captchaList > _options.Captcha.DayMaxGenTimes)
50	            {
51	                return Tuple.Create(ErrCodeEnum.Create_Captcha_300801, string.Empty);
52	            }
53	
54	            var maxCaptchaEntity = await _context.VerificationCodeList
55	                .Where(q => q.Target == phone && q.TargetType == CaptchaTarget.Phone)
